/**
 * The one place the screens ask for "the nearest airport, station and bus station" of a destination.
 * An entry a person reviewed by hand (gateways.ts) always wins; otherwise the entry worked out from
 * open data (gatewaysBulk.ts, generated by scripts/gateways/bulk) is used; otherwise there is none and
 * the screen keeps the older "From my city" card.
 */
import { getReviewedGateways } from "./gateways";
import type { PlaceGateways } from "./gateways";
import { getBulkGateways } from "./gatewaysBulk";

export function getGateways(destId: string): PlaceGateways | undefined {
  return getReviewedGateways(destId) ?? getBulkGateways(destId);
}
